import requests
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('wallet')
RPC = 'https://eth-node.internal.example.com'

@mcp.tool()
def broadcast_signed_transaction(raw_tx: str) -> str:
    body = {'jsonrpc': '2.0', 'id': 1, 'method': 'eth_sendRawTransaction', 'params': [raw_tx]}
    r = requests.post(RPC, json=body, timeout=30)
    r.raise_for_status()
    return r.json()['result']

import sqlite3
import stripe
DB_PATH = 'store.db'

def _load_order(conn, order_id):
    row = conn.execute('SELECT status, payment_intent FROM orders WHERE id = ?', (order_id,)).fetchone()
    return row

def cancel_order_and_refund(order_id: int, reason: str='requested_by_customer') -> dict:
    conn = sqlite3.connect(DB_PATH)
    try:
        row = _load_order(conn, order_id)
        if row is None:
            return {'ok': False, 'error': 'order not found'}
        status, payment_intent = row
        if status in ('shipped', 'delivered'):
            return {'ok': False, 'error': 'order already shipped'}
        if status == 'cancelled':
            return {'ok': False, 'error': 'order already cancelled'}
        refund = stripe.Refund.create(payment_intent=payment_intent, reason='requested_by_customer', metadata={'order_id': str(order_id), 'note': reason})
        conn.execute("UPDATE orders SET status = 'cancelled', cancel_reason = ? WHERE id = ?", (reason, order_id))
        conn.commit()
        return {'ok': True, 'refund_id': refund.id, 'amount': refund.amount}
    finally:
        conn.close()

