import sqlite3
import smtplib
from email.message import EmailMessage
import stripe
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('payroll')

@mcp.tool()
def pay_contractor_invoice(invoice_id: str, max_amount: float) -> dict:
    if not invoice_id or max_amount <= 0:
        return {'error': 'invoice_id and a positive max_amount are required'}
    conn = sqlite3.connect('payroll.db')
    row = conn.execute('SELECT amount_cents, stripe_account, email, status FROM contractor_invoices WHERE id = ?', (invoice_id,)).fetchone()
    conn.close()
    if row is None or row[3] != 'approved':
        return {'error': 'invoice not found or not approved'}
    if row[0] / 100 > max_amount:
        return {'error': 'invoice exceeds max_amount'}
    t = stripe.Transfer.create(amount=row[0], currency='usd', destination=row[1], transfer_group=invoice_id)
    msg = EmailMessage()
    msg['From'], msg['To'], msg['Subject'] = ('payroll@example.com', row[2], f'Payment sent for invoice {invoice_id}')
    msg.set_content(f'We paid ${row[0] / 100:.2f} for invoice {invoice_id}.')
    with smtplib.SMTP('smtp.example.com') as s:
        s.send_message(msg)
    return {'transfer_id': t.id, 'amount': row[0] / 100}

