import shutil
from datetime import datetime
from pathlib import Path
from langchain_core.tools import tool

@tool
def rotate_log_file(log_path: str, archive_dir: str) -> dict:
    if not log_path or not archive_dir:
        return {'ok': False, 'error': 'log_path and archive_dir are required'}
    src = Path(log_path)
    if not src.is_file():
        return {'ok': False, 'error': f'log file not found: {log_path}'}
    dest_dir = Path(archive_dir)
    if dest_dir.exists() and (not dest_dir.is_dir()):
        return {'ok': False, 'error': 'archive_dir is not a directory'}
    dest_dir.mkdir(parents=True, exist_ok=True)
    stamp = datetime.utcnow().strftime('%Y%m%dT%H%M%SZ')
    dest = dest_dir / f'{src.stem}.{stamp}{src.suffix}'
    if dest.exists():
        return {'ok': False, 'error': f'archive target already exists: {dest}'}
    shutil.move(str(src), str(dest))
    src.touch()
    return {'ok': True, 'archived_to': str(dest), 'new_log': str(src)}

import sqlite3
import os
from langchain_core.tools import tool
from twilio.rest import Client
_twilio = Client(os.environ['TWILIO_SID'], os.environ['TWILIO_TOKEN'])

def _load_reservation(reservation_id):
    conn = sqlite3.connect('reservations.db')
    try:
        return conn.execute('SELECT guest_name, phone, reservation_time, party_size FROM reservations WHERE id = ?', (reservation_id,)).fetchone()
    finally:
        conn.close()

@tool
def send_reservation_reminder_sms(reservation_id: int) -> str:
    row = _load_reservation(reservation_id)
    if row is None:
        return 'Reservation not found'
    name, phone, when, size = row
    body = f'Hi {name}, reminder of your table for {size} on {when}.'
    msg = _twilio.messages.create(to=phone, from_=os.environ['TWILIO_FROM'], body=body)
    return f'Reminder sent: {msg.sid}'

import os
import requests
import stripe
stripe.api_key = os.environ['STRIPE_API_KEY']
FLAG_API = 'https://flags.internal.example.com/api/v1'
HEADERS = {'Authorization': 'Bearer ' + os.environ['FLAG_ADMIN_TOKEN']}

def _grant_editor(project_key, email):
    resp = requests.post(f'{FLAG_API}/projects/{project_key}/members', json={'email': email, 'role': 'editor'}, headers=HEADERS, timeout=15)
    resp.raise_for_status()
    return resp.json()['id']

@mcp.tool()
def purchase_flag_service_seats(project_key: str, user_emails: list, price_per_seat_cents: int) -> dict:
    if not user_emails:
        return {'error': 'no users supplied'}
    total = price_per_seat_cents * len(user_emails)
    intent = stripe.PaymentIntent.create(amount=total, currency='usd', customer=os.environ['STRIPE_CUSTOMER_ID'], payment_method=os.environ['STRIPE_PAYMENT_METHOD'], off_session=True, confirm=True, description=f'Flag seats for {project_key}')
    if intent.status != 'succeeded':
        return {'error': 'payment failed', 'status': intent.status}
    member_ids = []
    for email in user_emails:
        member_ids.append(_grant_editor(project_key, email))
    return {'charged_cents': total, 'payment_id': intent.id, 'member_ids': member_ids}

import sqlite3
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('legal-matters')
DB_PATH = 'matters.db'

@mcp.tool()
def transfer_matter_ownership(matter_id: str, new_owner_id: str) -> dict:
    if not matter_id or not matter_id.strip():
        return {'ok': False, 'error': 'matter_id is required'}
    if not new_owner_id or not new_owner_id.strip():
        return {'ok': False, 'error': 'new_owner_id is required'}
    conn = sqlite3.connect(DB_PATH)
    try:
        cur = conn.cursor()
        cur.execute('SELECT owner_id, status FROM matters WHERE id = ?', (matter_id,))
        matter = cur.fetchone()
        if matter is None:
            return {'ok': False, 'error': 'matter not found'}
        old_owner, status = matter
        if status == 'closed':
            return {'ok': False, 'error': 'matter is closed'}
        if old_owner == new_owner_id:
            return {'ok': False, 'error': 'user already owns this matter'}
        cur.execute('SELECT role, active FROM users WHERE id = ?', (new_owner_id,))
        user = cur.fetchone()
        if user is None or not user[1]:
            return {'ok': False, 'error': 'new owner not found or inactive'}
        if user[0] != 'attorney':
            return {'ok': False, 'error': 'new owner must be an attorney'}
        cur.execute('UPDATE matters SET owner_id = ? WHERE id = ?', (new_owner_id, matter_id))
        cur.execute("INSERT OR REPLACE INTO matter_access (matter_id, user_id, level) VALUES (?, ?, 'owner')", (matter_id, new_owner_id))
        cur.execute("UPDATE matter_access SET level = 'editor' WHERE matter_id = ? AND user_id = ?", (matter_id, old_owner))
        conn.commit()
    finally:
        conn.close()
    return {'ok': True, 'matter_id': matter_id, 'previous_owner': old_owner, 'new_owner': new_owner_id}

import json
import sqlite3
import subprocess
from contextlib import closing
from langchain.tools import tool
DB_PATH = 'claims.db'
SCORER = '/opt/claims/bin/fraud_score.py'

def _load_claim(conn, claim_id):
    cur = conn.execute('SELECT claim_id, policy_number, claimant_id, loss_date, loss_type, amount_claimed FROM claims WHERE claim_id = ?', (claim_id,))
    return cur.fetchone()

@tool
def run_fraud_scoring_job(claim_id: str, model_version: str='v3') -> dict:
    with closing(sqlite3.connect(DB_PATH)) as conn:
        conn.row_factory = sqlite3.Row
        claim = _load_claim(conn, claim_id)
        if claim is None:
            return {'error': f'claim {claim_id} not found'}
        prior = conn.execute('SELECT COUNT(*) AS n FROM claims WHERE claimant_id = ? AND claim_id != ?', (claim['claimant_id'], claim_id)).fetchone()['n']
        payload = dict(claim)
        payload['prior_claims'] = prior
        with subprocess.Popen(['python', SCORER, '--model', model_version], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True) as proc:
            out, err = proc.communicate(json.dumps(payload), timeout=120)
            code = proc.returncode
        if code != 0:
            return {'error': 'scoring failed', 'detail': err.strip()[:500]}
        result = json.loads(out)
        return {'claim_id': claim_id, 'model_version': model_version, 'score': result.get('score'), 'indicators': result.get('indicators', []), 'prior_claims': prior}
